Java Implementation (AirportSimulation.java):
```java
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class AirportSimulation {
    static final Semaphore runway = new Semaphore(1, true);
    static final Semaphore grounds = new Semaphore(3, true);
    static final Semaphore gates = new Semaphore(3, true);
    static final Object refuelTruck = new Object();
    static final AtomicInteger planesServed = new AtomicInteger();
    static final AtomicInteger totalPassengers = new AtomicInteger();

    static class Plane implements Comparable<Plane>, Runnable {
        final int id, passengers;
        final boolean isEmergency;
        final long arrivalTime = System.currentTimeMillis();

        Plane(int id, int passengers, boolean isEmergency) {
            this.id = id; this.passengers = passengers; this.isEmergency = isEmergency;
        }

        public int compareTo(Plane o) {
            if (this.isEmergency != o.isEmergency) return this.isEmergency ? -1 : 1;
            return Long.compare(this.arrivalTime, o.arrivalTime);
        }

        public void run() {
            try {
                System.out.printf("[%s] Plane %d: Requesting landing (Emergency=%b)%n",
                    Thread.currentThread().getName(), id, isEmergency);
                grounds.acquire();
                runway.acquire();
                System.out.printf("[%s] Plane %d: Landed on runway, coasting to gate%n", Thread.currentThread().getName(), id);
                runway.release();

                gates.acquire();
                System.out.printf("[%s] Plane %d: Docked at gate. Disembarking%n", Thread.currentThread().getName(), id);
                Thread.sleep(100);

                Thread cleaning = new Thread(() -> {
                    System.out.printf("[%s] Plane %d: Refilling supplies and cleaning%n", Thread.currentThread().getName(), id);
                }, "Thread-Service-" + id);
                cleaning.start();

                synchronized (refuelTruck) {
                    System.out.printf("[%s] Plane %d: Refuelling exclusively%n", Thread.currentThread().getName(), id);
                    Thread.sleep(150);
                }
                cleaning.join();

                System.out.printf("[Thread-Passenger-%d] Boarding Plane %d (%d pax)%n", id, id, passengers);
                totalPassengers.addAndGet(passengers);
                gates.release();

                runway.acquire();
                System.out.printf("[%s] Plane %d: Taking off from runway%n", Thread.currentThread().getName(), id);
                runway.release();
                grounds.release();
                planesServed.incrementAndGet();
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("[Thread-ATC] Simulation started.");
        ExecutorService pool = Executors.newFixedThreadPool(6);
        for (int i = 1; i <= 6; i++) {
            pool.execute(new Plane(i, 40 + i, i == 3));
            Thread.sleep(200);
        }
        pool.shutdown();
        pool.awaitTermination(60, TimeUnit.SECONDS);
        System.out.printf("[Thread-ATC] Sanity check: Gates empty (%d). Planes served: %d, Passengers: %d%n",
            gates.availablePermits(), planesServed.get(), totalPassengers.get());
    }
}
```
Assumptions:
- Maximum 3 planes on grounds managed via grounds Semaphore(3).
- Single runway mutually exclusive via runway Semaphore(1).
- 3 gates operate concurrently with gates Semaphore(3).
- Refueling truck is exclusive using synchronized monitor lock.
- Emergency plane given scheduling priority upon arrival.
